#include "core/ARModel.h"

#include <filament/Box.h>
#include <filament/Engine.h>
#include <filament/IndirectLight.h>
#include <filament/LightManager.h>
#include <filament/Scene.h>
#include <math/vec3.h>
#include <utils/EntityManager.h>
#include <gltfio/AssetLoader.h>
#include <gltfio/FilamentAsset.h>
#include <gltfio/MaterialProvider.h>
#include <gltfio/ResourceLoader.h>
#include <gltfio/TextureProvider.h>

#include "materials/uberarchive.h" // generated by Filament's gltfio build (uberz + resgen)

#include <cstdio>
#include <fstream>
#include <iterator>
#include <vector>

using namespace filament;

ARModelLoader::ARModelLoader(Engine *engine, Scene *scene) : engine(engine), scene(scene) {}

// glTF materials are lit (PBR) while the rest of the scene is unlit, so the scene has no light:
// add a sun (from above, behind the camera) and, unless the app set one, a uniform ambient light.
void ARModelLoader::addDefaultLighting() {
  sun = utils::EntityManager::get().create();
  LightManager::Builder(LightManager::Type::SUN)
      .color({1.0f, 1.0f, 1.0f})
      .intensity(110000.0f) // lux, for Filament's default camera exposure
      .direction({0.2f, -0.6f, -0.8f})
      .castShadows(false)
      .build(*engine, sun);
  scene->addEntity(sun);

  if (!scene->getIndirectLight()) {
    const math::float3 irradiance[1] = {{0.8f, 0.8f, 0.8f}}; // one SH band: uniform ambient
    ambient = IndirectLight::Builder().irradiance(1, irradiance).intensity(30000.0f).build(*engine);
    scene->setIndirectLight(ambient);
  }
}

ARModelLoader::~ARModelLoader() {
  if (!sun.isNull()) {
    scene->remove(sun);
    engine->destroy(sun);
    utils::EntityManager::get().destroy(sun);
  }
  if (ambient) {
    if (scene->getIndirectLight() == ambient) scene->setIndirectLight(nullptr);
    engine->destroy(ambient);
  }
  for (gltfio::FilamentAsset *asset : assets) {
    scene->removeEntities(asset->getEntities(), asset->getEntityCount());
    loader->destroyAsset(asset);
  }
  if (loader) gltfio::AssetLoader::destroy(&loader);
  delete imageDecoder;
  if (materials) {
    materials->destroyMaterials();
    delete materials;
  }
}

int ARModelLoader::load(const std::string &path) {
  std::ifstream in(path, std::ios::binary);
  if (!in) {
    printf("ERROR: loadModel: cannot open %s\n", path.c_str());
    return AR_MODEL_NOT_FOUND;
  }
  const std::vector<uint8_t> data((std::istreambuf_iterator<char>(in)),
                                  std::istreambuf_iterator<char>());

  if (!loader) {
    materials = gltfio::createUbershaderProvider(engine, UBERARCHIVE_DEFAULT_DATA,
                                                 UBERARCHIVE_DEFAULT_SIZE);
    gltfio::AssetConfiguration config{};
    config.engine = engine;
    config.materials = materials;
    loader = gltfio::AssetLoader::create(config);
    imageDecoder = gltfio::createStbProvider(engine);
    addDefaultLighting();
  }

  gltfio::FilamentAsset *asset =
      loader->createAsset(data.data(), static_cast<uint32_t>(data.size()));
  if (!asset) {
    printf("ERROR: loadModel: %s is not a glTF / GLB that gltfio can load\n", path.c_str());
    return AR_MODEL_INVALID;
  }

  // Buffers and textures: embedded in a .glb, or next to a .gltf (path's directory).
  gltfio::ResourceConfiguration resources{};
  resources.engine = engine;
  resources.gltfPath = path.c_str();
  resources.normalizeSkinningWeights = true;
  gltfio::ResourceLoader resourceLoader(resources);
  resourceLoader.addTextureProvider("image/png", imageDecoder);
  resourceLoader.addTextureProvider("image/jpeg", imageDecoder);
  if (!resourceLoader.loadResources(asset)) {
    printf("ERROR: loadModel: the resources of %s could not be loaded\n", path.c_str());
    loader->destroyAsset(asset);
    return AR_MODEL_INVALID;
  }
  asset->releaseSourceData();

  scene->addEntities(asset->getEntities(), asset->getEntityCount());
  assets.push_back(asset);
  printf("Model loaded: %s (%zu entities)\n", path.c_str(), asset->getEntityCount());
  return static_cast<int>(assets.size() - 1);
}

utils::Entity ARModelLoader::root(int handle) const {
  if (handle < 0 || handle >= static_cast<int>(assets.size())) return utils::Entity();
  return assets[handle]->getRoot();
}

void ARModelLoader::setVisible(int handle, bool visible) {
  if (handle < 0 || handle >= static_cast<int>(assets.size())) return;
  gltfio::FilamentAsset *asset = assets[handle];
  if (visible) {
    scene->addEntities(asset->getEntities(), asset->getEntityCount());
  } else {
    scene->removeEntities(asset->getEntities(), asset->getEntityCount());
  }
}

bool ARModelLoader::bounds(int handle, float min[3], float max[3]) const {
  if (handle < 0 || handle >= static_cast<int>(assets.size())) return false;
  const Aabb box = assets[handle]->getBoundingBox();
  for (int i = 0; i < 3; ++i) {
    min[i] = box.min[i];
    max[i] = box.max[i];
  }
  return true;
}
